53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const COMPONENT_TYPES = ["rune", "moonstone"];
65	const COMPONENT_BLOCK_SIZE = 3;
66	const COMPONENT_BLOCK_PREMIUM = 60;
67	
68	const CURSE_SURCHARGE_PERCENT = 50;
69	const HIGH_ENCHANTMENT_THRESHOLD = 5;
70	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
71	
72	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
73	const LOYALTY_DISCOUNT_PERCENT = 20;
74	const LOYALTY_MINIMUM_YEARS = 2;
75	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
76	
77	// Integer multiply before divide keeps fractional percentages exact
78	// (e.g. 10% of 25 is exactly 2.5 — no float noise from multiplying by 1.1).
79	const percentOf = (amount: number, percent: number): number =>
80	  (amount * percent) / 100;
81	
82	const isComponent = (item: QuoteItem): boolean =>
83	  COMPONENT_TYPES.includes(item.type);
84	
85	const basePremiumOf = (item: QuoteItem): number => {
86	  const premium = BASE_PREMIUMS[item.type];
87	  if (premium === undefined) {
88	    throw new Error(`unknown item type: ${item.type}`);
89	  }
90	  return premium;
91	};
92	
93	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
94	  values.reduce((sum, value) => sum + amount(value), 0);
95	
96	const isCursed = (item: QuoteItem): boolean => item.cursed === true;
97	
98	const isHighlyEnchanted = (item: QuoteItem): boolean =>
99	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
100	
101	// Item surcharge: a fixed percent of each qualifying item's base premium.
102	const itemSurcharge = (
103	  items: QuoteItem[],
104	  applies: (item: QuoteItem) => boolean,
105	  percent: number
106	): number =>
107	  sumBy(items.filter(applies), (item) => percentOf(basePremiumOf(item), percent));
108	
109	// Pricing rule: a block of exactly 3 alike components costs a flat block premium.
110	const componentTypePremium = (items: QuoteItem[], type: string): number => {
111	  const count = items.filter((item) => item.type === type).length;
112	  return count === COMPONENT_BLOCK_SIZE
113	    ? COMPONENT_BLOCK_PREMIUM
114	    : count * BASE_PREMIUMS[type];
115	};
116	
117	const quotePremium = (
118	  items: QuoteItem[],
119	  customer: Customer,
120	  isFollowUpContract: boolean
121	): number => {
122	  const componentsPremium = sumBy(COMPONENT_TYPES, (type) =>
123	    componentTypePremium(items, type)
124	  );
125	  const mainItemsPremium = sumBy(
126	    items.filter((item) => !isComponent(item)),
127	    basePremiumOf
128	  );
129	  const policyBasePremium = componentsPremium + mainItemsPremium;
130	  const curseSurcharge = itemSurcharge(items, isCursed, CURSE_SURCHARGE_PERCENT);
131	  const enchantmentSurcharge = itemSurcharge(
132	    items,
133	    isHighlyEnchanted,
134	    HIGH_ENCHANTMENT_SURCHARGE_PERCENT
135	  );
136	  // Policy-wide modifiers are all computed on the unmodified policy base.
137	  const firstInsuranceSurcharge = percentOf(
138	    policyBasePremium,
139	    FIRST_INSURANCE_SURCHARGE_PERCENT
140	  );
141	  const loyaltyDiscount =
142	    customer.yearsWithMHPCO >= LOYALTY_MINIMUM_YEARS
143	      ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT)
144	      : 0;
145	  const followUpContractDiscount = isFollowUpContract
146	    ? percentOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
147	    : 0;
148	  return Math.ceil(
149	    policyBasePremium +
150	      curseSurcharge +
151	      enchantmentSurcharge +
152	      firstInsuranceSurcharge -
153	      loyaltyDiscount -
154	      followUpContractDiscount +
155	      PROCESSING_FEE
156	  );
157	};
158	
159	const INSURANCE_VALUES: Record<string, number> = {
160	  sword: 1000,
161	  amulet: 600,
162	  rune: 250,
163	};
164	
165	const DEDUCTIBLE = 100;
166	const CAP_MULTIPLIER = 2; // payout cap is twice the policy's insurance sum
167	
168	const insuranceSumOf = (items: QuoteItem[]): number =>
169	  sumBy(items, (item) => INSURANCE_VALUES[item.type]);
170	
171	// Claim clause: items enchanted at or above this level are only reimbursed
172	// at 50%. Distinct rule from the premium's HIGH_ENCHANTMENT_THRESHOLD (5).
173	const CLAIM_HALVING_ENCHANTMENT_THRESHOLD = 8;
174	const HALVED_REIMBURSEMENT_PERCENT = 50;
175	
176	const reimbursementFor = (
177	  policyItems: QuoteItem[],
178	  damage: Damage
179	): number => {
180	  const insuredItem = policyItems.find(
181	    (item) => item.type === damage.itemType
182	  );
183	  return (insuredItem?.enchantment ?? 0) >= CLAIM_HALVING_ENCHANTMENT_THRESHOLD
184	    ? percentOf(damage.amount, HALVED_REIMBURSEMENT_PERCENT)
185	    : damage.amount;
186	};
187	
188	// A policy is what a quote step creates: the insured items plus the payout
189	// cap that later claims against this policy draw down.
190	interface Policy {
191	  items: QuoteItem[];
192	  remainingCap: number;
193	}
194	
195	const openPolicy = (items: QuoteItem[]): Policy => ({
196	  items,
197	  remainingCap: CAP_MULTIPLIER * insuranceSumOf(items),
198	});
199	
200	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
201	  // Payouts round down in MHPCO's favor — mirrors the Math.ceil on premiums.
202	  const uncappedPayout = Math.floor(
203	    sumBy(damages, (damage) => reimbursementFor(policy.items, damage) - DEDUCTIBLE)
204	  );
205	  const payout = Math.min(uncappedPayout, policy.remainingCap);
206	  return { payout, remainingCap: policy.remainingCap - payout };
207	};
208	
209	export const runScenario = (scenario: Scenario): ScenarioResult => {
210	  // Indexed by step index — claim steps reference their policy that way.
211	  const policies: Policy[] = [];
212	  const results = scenario.steps.map((step, index): StepResult => {
213	    if (step.op === "quote") {
214	      policies[index] = openPolicy(step.items);
215	      return {
216	        premium: quotePremium(step.items, scenario.customer, index > 0),
217	      };
218	    }
219	    const policy = policies[step.policy];
220	    const result = settleClaim(policy, step.incident.damages);
221	    policy.remainingCap = result.remainingCap;
222	    return result;
223	  });
224	  return { results };
225	};
226

